theorem IsComplexLinear.comp {F : V →ₗ[ℝ] W} {G : W →ₗ[ℝ] U}
    (hG : IsComplexLinear J' J'' G) (hF : IsComplexLinear J J' F) :
    IsComplexLinear J J'' (G ∘ₗ F)

theorem IsComplexAntilinear.comp {F : V →ₗ[ℝ] W} {G : W →ₗ[ℝ] U}
    (hG : IsComplexAntilinear J' J'' G) (hF : IsComplexAntilinear J J' F) :
    IsComplexLinear J J'' (G ∘ₗ F)

theorem IsComplexLinear.comp_antilinear {F : V →ₗ[ℝ] W} {G : W →ₗ[ℝ] U}
    (hG : IsComplexLinear J' J'' G) (hF : IsComplexAntilinear J J' F) :
    IsComplexAntilinear J J'' (G ∘ₗ F)

theorem IsComplexAntilinear.comp_linear {F : V →ₗ[ℝ] W} {G : W →ₗ[ℝ] U}
    (hG : IsComplexAntilinear J' J'' G) (hF : IsComplexLinear J J' F) :
    IsComplexAntilinear J J'' (G ∘ₗ F)

theorem IsComplexLinear.complexAntilinearPart_eq_zero {F : V →ₗ[ℝ] W}
    (h : IsComplexLinear J J' F) (hJ' : J' ∘ₗ J' = -LinearMap.id) :
    complexAntilinearPart J J' F = 0

theorem IsComplexAntilinear.complexAntilinearPart_eq {F : V →ₗ[ℝ] W}
    (h : IsComplexAntilinear J J' F) (hJ' : J' ∘ₗ J' = -LinearMap.id) :
    complexAntilinearPart J J' F = F

theorem IsComplexAntilinear.complexLinearPart_eq_zero {F : V →ₗ[ℝ] W}
    (h : IsComplexAntilinear J J' F) (hJ' : J' ∘ₗ J' = -LinearMap.id) :
    complexLinearPart J J' F = 0

def orthogonalGroupToLinearIsometryEquiv :
    Matrix.orthogonalGroup ι ℝ →*
      (EuclideanSpace ℝ ι ≃ₗᵢ[ℝ] EuclideanSpace ℝ ι)

theorem ofIdx_smul_notMem_dominantChamber {i : ι} (hi : i ∈ b.support) {x : M}
    (hx : x ∈ openDominantChamber P b) :
    RootPairing.weylGroup.ofIdx P i • x ∉ dominantChamber P b

theorem ofIdx_smul_ne_of_mem_openDominantChamber {i : ι} (hi : i ∈ b.support) {x : M}
    (hx : x ∈ openDominantChamber P b) :
    RootPairing.weylGroup.ofIdx P i • x ≠ x

theorem HasCartanType.isSimplyLaced_iff_of_valid {b : P.Base} {t : DynkinType}
    (h : HasCartanType P b t) (ht : t.Valid) :
    b.cartanMatrix.IsSimplyLaced ↔ t.IsSimplyLaced

theorem image_root_inversions :
    P.root '' inversions P b w =
      (P.root '' posRoots P b) ∩ {α | w • α ∈ P.root '' negRoots P b}

lemma reflectionPerm_mem_inversions_sdiff (v : P.weylGroup) {i j : ι}
    (hi : i ∈ b.support) (hj : b.IsPos j) (hji : j ≠ i)
    (hneg : ¬ b.IsPos (P.weylGroupToPerm v (P.reflectionPerm i j))) :
    P.reflectionPerm i j ∈ inversions P b v \ {i}

def puncturedInversionsEquiv {i : ι} (hi : i ∈ b.support) :
    ↥(inversions P b (w * RootPairing.weylGroup.ofIdx P i) \ {i}) ≃
      ↥(inversions P b w \ {i})
